const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const walvisBay = ee.Geometry.Point([14.5053, -22.9576]);
  const region = walvisBay.buffer(10000); // 10km radius

  // 2. Cloud masking function for Landsat 8/9
  function maskL8Clouds(image) {
    const qa = image.select('QA_PIXEL');
    const cloudMask = qa.bitwiseAnd(1 << 3).eq(0) // Cloud
                        .and(qa.bitwiseAnd(1 << 4).eq(0)); // Cloud shadow
    return image.updateMask(cloudMask);
  }

  // 3. NDVI calculation function
  function addNDVI(image) {
    const ndvi = image.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI');
    return image.addBands(ndvi);
  }

  // 4. Data Acquisition - February 2021
  let col2021 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(region)
    .filter(ee.Filter.calendarRange(2021, 2021, 'year'))
    .filter(ee.Filter.calendarRange(2, 2, 'month'))
    .map(maskL8Clouds)
    .map(addNDVI);

  const size2021 = col2021.size().getInfo();
  console.log(`February 2021 Images: ${size2021}`);

  if (size2021 === 0) {
    // Try Landsat 9
    col2021 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
      .filterBounds(region)
      .filter(ee.Filter.calendarRange(2021, 2021, 'year'))
      .filter(ee.Filter.calendarRange(2, 2, 'month'))
      .map(maskL8Clouds)
      .map(addNDVI);

    const size2021_L9 = col2021.size().getInfo();
    console.log(`February 2021 Images (L9): ${size2021_L9}`);

    if (size2021_L9 === 0) {
      console.log("No data for February 2021.");
      console.log("<answer>C1</answer>");
      return;
    }
  }

  // 5. Data Acquisition - February 2010-2020 average
  const col2010_2020 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(region)
    .filter(ee.Filter.calendarRange(2010, 2020, 'year'))
    .filter(ee.Filter.calendarRange(2, 2, 'month'))
    .map(maskL8Clouds)
    .map(addNDVI);

  const sizeBaseline = col2010_2020.size().getInfo();
  console.log(`February 2010-2020 Images: ${sizeBaseline}`);

  if (sizeBaseline === 0) {
    console.log("No data for February 2010-2020.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 6. Calculate mean NDVI for 2021
  const ndvi2021 = col2021.select('NDVI').mean();

  const stats2021 = ndvi2021.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const mean2021 = stats2021['NDVI_mean'];
  const count2021 = stats2021['NDVI_count'];

  console.log(`2021: Mean NDVI = ${mean2021}, Pixels = ${count2021}`);

  if (count2021 === 0 || count2021 === null) {
    console.log("No valid pixels for 2021 after masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 7. Calculate mean NDVI for 2010-2020
  const ndviBaseline = col2010_2020.select('NDVI').mean();

  const statsBaseline = ndviBaseline.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const meanBaseline = statsBaseline['NDVI_mean'];
  const countBaseline = statsBaseline['NDVI_count'];

  console.log(`2010-2020: Mean NDVI = ${meanBaseline}, Pixels = ${countBaseline}`);

  if (countBaseline === 0 || countBaseline === null) {
    console.log("No valid pixels for 2010-2020 after masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 8. Validation & Final Answer
  if (mean2021 === null || meanBaseline === null || 
      isNaN(mean2021) || isNaN(meanBaseline) ||
      mean2021 < -1 || mean2021 > 1 || meanBaseline < -1 || meanBaseline > 1) {
    console.log("Invalid NDVI calculation.");
    console.log("<answer>C3</answer>");
    return;
  }

  console.log(`Difference: ${(mean2021 - meanBaseline).toFixed(4)}`);

  if (mean2021 > meanBaseline) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
